+++ b/test_exception_fix.py
@@ -0,0 +1,32 @@
+import pyparsing as pp
+
+# Create a simple parser element with a custom error message
+class CustomParser(pp.ParserElement):
+    def __init__(self):
+        super().__init__()
+        self.errmsg = "Generic error message"
+        self.customName = "CustomParser"
+        
+    def parseImpl(self, instring, loc, do_actions=True):
+        # Always fail
+        print("CustomParser.parseImpl called")
+        raise pp.ParseException(instring, loc, "Detailed error from CustomParser", self)
+        
+    def _generateDefaultName(self):
+        return "CustomParser"
+
+# Create a ParseElementEnhance wrapper around it that requires the parser to match
+# Using And (which is also a ParseElementEnhance subclass) to force matching
+enhanced_parser = CustomParser() + pp.Literal("required")
+
+print("Attempting to parse")
+try:
+    # Try to parse something - this should preserve the detailed error message
+    # from CustomParser rather than replacing it with the generic one
+    result = enhanced_parser.parse_string("anything")
+    print("Parse succeeded unexpectedly")
+except pp.ParseException as e:
+    print(f"Exception message: {e}")
+    print(f"Exception location: {e.loc}")
+except Exception as e:
+    print(f"Unexpected exception: {type(e).__name__}: {e}")
